1	package numeric
2	
3	import (
4		"fmt"
5		"os"
6		"sync"
7		"sync/atomic"
8		"time"
9	)
10	
11	// Clock 用于注入时间来源，主要服务于确定性测试；生产代码使用墙钟。
12	type Clock interface {
13		Now() time.Time
14	}
15	
16	type wallClock struct{}
17	
18	func (wallClock) Now() time.Time { return time.Now().UTC() }
19	
20	// Option 配置 [Open] 的行为。
21	type Option func(*Store)
22	
23	// WithClock 注入自定义时钟。
24	func WithClock(c Clock) Option {
25		return func(s *Store) { s.now = c.Now }
26	}
27	
28	// Store 是本地数值作业归档：负责提交、调度、取消、查询与持久化。
29	//
30	// 一次只运行一个作业；所有方法可被多个 goroutine 并发调用。
31	// idemIdentity 是幂等作用域（提交人, 请求号）的复合键。两个字段都按调用方
32	// 给出的完整字符串逐字节参与比较，允许包含 U+0000 与非法 UTF-8 字节
33	// （后者靠记录中的 identity_raw 兜底字段跨重开保真）。不能用分隔符把两个
34	// 字段拼成单个字符串：提交人 "a"、请求号 "b\x00c" 与提交人 "a\x00b"、
35	// 请求号 "c" 在任何分隔符方案下都会产生歧义（分隔符本身可以出现在字段内部）。
36	type idemIdentity struct {
37		submitter string
38		requestID string
39	}
40	
41	type Store struct {
42		dir string
43	
44		mu     sync.Mutex
45		jobs   []*storedJob // 严格按作业号（即提交先后）排列
46		byID   map[uint64]*storedJob
47		idem   map[idemIdentity]uint64 // (提交人, 请求号) -> 作业号
48		nextID uint64
49		closed bool
50	
51		now func() time.Time
52	
53		runningID uint64
54		waitCh    chan struct{}
55		stopCh    chan struct{}
56		stopping  atomic.Bool
57		wg        sync.WaitGroup
58	
59		// compute 仅用于包内确定性测试：若为空则使用真实的 [computeResult]。
60		// 必须在任何 Submit 之前（Open 之后立即）设置；worker 只会在收到
61		// Submit 的唤醒之后读取它，因此与设置之间存在 happens-before 关系。
62		compute func(id uint64, inputs []int64, seed int64, canceled func() bool) (sum, sumSquares int64, reason string, ok bool)
63	
64		// persistFault 仅用于包内确定性测试：若非 nil，每次 persist 都会先调用它，
65		// 返回非 nil 即模拟该次记录保存失败（如同临时记录无法创建或原记录无法替换）。
66		// 生产代码恒为 nil。钩子可按作业号与“待保存的当前状态”只让某一次写入失败
67		// （例如仅让成功归档写入失败），而让其余记录照常落盘。
68		persistFault func(j *storedJob) error
69	}
70	
71	// Open 打开（必要时创建）目录 dir 并恢复其中的全部作业记录。
72	//
73	// 恢复语义：
74	//   - 已确认的提交、取消与完成结果原样保留，幂等请求号继续生效；
75	//   - 上次关闭时仍在运行的作业标记为失败（计算被中断）并阻止其下游；
76	//   - 排队作业继续排队并由本地唯一 worker 按提交先后处理；
77	//   - 成功状态始终与完整归档同时可见。
78	func Open(dir string, opts ...Option) (*Store, error) {
79		if err := os.MkdirAll(dir, 0o700); err != nil {
80			return nil, err
81		}
82		jobs, maxID, err := loadDir(dir)
83		if err != nil {
84			return nil, err
85		}
86		s := &Store{
87			dir:    dir,
88			jobs:   jobs,
89			byID:   make(map[uint64]*storedJob),
90			idem:   make(map[idemIdentity]uint64),
91			nextID: maxID + 1,
92			now:    wallClock{}.Now,
93			waitCh: make(chan struct{}, 1),
94			stopCh: make(chan struct{}),
95		}
96		for _, opt := range opts {
97			opt(s)
98		}
99		for _, j := range jobs {
100			s.byID[j.id] = j
101			if j.requestID != "" {
102				s.idem[idemIdentity{j.submitter, j.requestID}] = j.id
103			}
104		}
105		// 重建失败/取消作业对排队下游的阻断。
106		s.cascadeLocked()
107		s.wg.Add(1)
108		go s.worker()
109		return s, nil
110	}
111	
112	// Close 关闭归档。正在运行的作业会尽快中止并标记为失败（计算被中断），
113	// 排队作业原样保留在磁盘上，下次 [Open] 继续。
114	func (s *Store) Close() error {
115		s.mu.Lock()
116		if s.closed {
117			s.mu.Unlock()
118			return nil
119		}
120		s.closed = true
121		var running *storedJob
122		if s.runningID != 0 {
123			running = s.byID[s.runningID]
124		}
125		s.mu.Unlock()
126	
127		if s.stopping.CompareAndSwap(false, true) {
128			close(s.stopCh)
129		}
130		// 中止正在运行的计算。
131		if running != nil {
132			running.canceled.Store(true)
133		}
134		s.notify()
135		s.wg.Wait()
136		return nil
137	}
138	
139	// Submit 接受一次作业提交。
140	//
141	// 空序列返回 [ErrEmptySequence]；引用不存在的依赖返回
142	// [ErrDependencyNotFound]；同一提交人复用请求号但内容变化返回
143	// [ErrIdempotencyConflict]（同时返回原作业视图）——这些拒绝都不产生记录。
144	// 相同提交人+请求号+内容的重复提交（含并发重复）返回原作业及其当前状态。
145	func (s *Store) Submit(req SubmitRequest) (*Job, error) {
146		s.mu.Lock()
147		defer s.mu.Unlock()
148		if s.closed || s.stopping.Load() {
149			return nil, ErrStoreClosed
150		}
151		if len(req.Values) == 0 {
152			return nil, ErrEmptySequence
153		}
154		if err := s.validateDependenciesLocked(&req); err != nil {
155			return nil, err
156		}
157		deps := requestDeps(&req)
158		if req.RequestID != "" {
159			key := idemIdentity{req.Submitter, req.RequestID}
160			if origID, ok := s.idem[key]; ok {
161				orig := s.byID[origID]
162				if sameContent(orig, &req) {
163					return s.viewLocked(orig), nil
164				}
165				return s.viewLocked(orig),
166					fmt.Errorf("%w：提交人 %q 的请求号 %q 已用于作业 %d",
167						ErrIdempotencyConflict, req.Submitter, req.RequestID, origID)
168			}
169		}
170	
171		now := s.now().UTC()
172		j := &storedJob{
173			id:           s.nextID,
174			submitter:    req.Submitter,
175			requestID:    req.RequestID,
176			seed:         req.Seed,
177			values:       append([]int64(nil), req.Values...),
178			dependencies: append([]uint64(nil), deps...),
179			queuedAt:     now,
180			status:       StatusQueued,
181		}
182		// 先持久化，接受之后该提交即不可丢失。
183		if err := s.persist(j); err != nil {
184			return nil, err
185		}
186		s.nextID++
187		s.jobs = append(s.jobs, j)
188		s.byID[j.id] = j
189		if req.RequestID != "" {
190			s.idem[idemIdentity{req.Submitter, req.RequestID}] = j.id
191		}
192		// 依赖已失败/取消时，新接受的作业立刻进入失败终态。
193		s.cascadeLocked()
194		s.notifyLocked()
195		return s.viewLocked(j), nil
196	}
197	
198	// requestDeps 规范化一次提交的直接上游作业号列表：
199	// 非空 Dependencies 优先（保持次序）；否则单依赖方式退化为只含一个作业号的列表；
200	// 两者皆无则为 nil。调用前须先经 [Store.validateDependenciesLocked] 校验。
201	func requestDeps(req *SubmitRequest) []uint64 {
202		if len(req.Dependencies) > 0 {
203			return append([]uint64(nil), req.Dependencies...)
204		}
205		if req.HasDependency {
206			return []uint64{req.DependencyID}
207		}
208		return nil
209	}
210	
211	// validateDependenciesLocked 在持锁状态下校验提交的依赖列表：
212	//   - 单依赖方式与非空列表同时启用 → 拒绝；
213	//   - 列表含零或重复作业号 → 拒绝（错误指出具体作业号）；
214	//   - 列表引用提交时不存在的作业 → 拒绝。
215	//
216	// 任一拒绝都不产生记录，也不占用幂等请求号。
217	func (s *Store) validateDependenciesLocked(req *SubmitRequest) error {
218		if req.HasDependency && len(req.Dependencies) > 0 {
219			return fmt.Errorf("%w：单依赖方式与依赖列表不能同时启用", ErrInvalidDependency)
220		}
221		deps := requestDeps(req)
222		seen := make(map[uint64]struct{}, len(deps))
223		for _, id := range deps {
224			if id == 0 {
225				return fmt.Errorf("%w：依赖列表包含无效作业号 0", ErrInvalidDependency)
226			}
227			if _, dup := seen[id]; dup {
228				return fmt.Errorf("%w：依赖列表包含重复作业号 %d", ErrInvalidDependency, id)
229			}
230			seen[id] = struct{}{}
231		}
232		for _, id := range deps {
233			if s.byID[id] == nil {
234				return fmt.Errorf("%w：作业号 %d", ErrDependencyNotFound, id)
235			}
236		}
237		return nil
238	}
239	
240	// sameContent 判断两次提交的内容是否一致；整数次序或依赖列表（内容与次序）
241	// 不同即视为不同内容。单依赖方式与只含同一作业号的列表视为相同内容。
242	func sameContent(j *storedJob, req *SubmitRequest) bool {
243		if j.seed != req.Seed {
244			return false
245		}
246		rd := requestDeps(req)
247		if len(j.dependencies) != len(rd) {
248			return false
249		}
250		for i := range j.dependencies {
251			if j.dependencies[i] != rd[i] {
252				return false
253			}
254		}
255		if len(j.values) != len(req.Values) {
256			return false
257		}
258		for i := range j.values {
259			if j.values[i] != req.Values[i] {
260				return false
261			}
262		}
263		return true
264	}
265	
266	// Get 按作业号读取作业详情（含成功归档）；不存在返回 [ErrNotFound]。
267	func (s *Store) Get(id uint64) (*Job, error) {
268		s.mu.Lock()
269		defer s.mu.Unlock()
270		j := s.byID[id]
271		if j == nil {
272			return nil, fmt.Errorf("%w：作业号 %d", ErrNotFound, id)
273		}
274		return s.viewLocked(j), nil
275	}
276	
277	// Cancel 请求取消作业。
278	//
279	// 排队或运行中的作业都可以取消；取消以“取消状态已成功保存进归档记录”为生效
280	// 条件：只有原子替换原记录成功后，返回结果、可查询状态与磁盘记录才一致地呈现
281	// 为取消，该作业及依赖它的作业才不会再产生成功归档。若取消记录无法创建临时
282	// 文件或无法替换原记录，返回的是实际保存错误，作业保持原状——不新增完成时间、
283	// 不清空原有信息、不中止正在运行的计算、不级联标记下游，排队与调度规则不变；
284	// 写入条件恢复后对仍处于排队或运行状态的同一作业再次取消会重新尝试保存。
285	// 重复取消已取消的作业仍返回成功；对已成功或已失败的作业取消返回
286	// [ErrNotCancellable]，原结果保持不变（计算在两次取消请求之间完成时亦然）。
287	func (s *Store) Cancel(id uint64) (*Job, error) {
288		s.mu.Lock()
289		defer s.mu.Unlock()
290		if s.closed {
291			return nil, ErrStoreClosed
292		}
293		j := s.byID[id]
294		if j == nil {
295			return nil, fmt.Errorf("%w：作业号 %d", ErrNotFound, id)
296		}
297		switch j.status {
298		case StatusCanceled:
299			return s.viewLocked(j), nil
300		case StatusSucceeded, StatusFailed:
301			return s.viewLocked(j),
302				fmt.Errorf("%w：作业 %d 当前状态为 %s", ErrNotCancellable, id, j.status)
303		}
304	
305		// queued / running：先把取消终态写入原记录，确认原子替换成功后才让取消
306		// 生效。持锁期间外界观察不到中间态；若创建临时记录或替换原记录失败，
307		// 必须逐字段回滚，内存与磁盘都保持取消前的原状并返回实际保存错误，
308		// 不能把这次取消当作已完成。
309		now := s.now().UTC()
310		prevStatus := j.status
311		prevFinishedAt := j.finishedAt
312		prevReason := j.failureReason
313		prevBlocker := j.blockerID
314		prevEffective := j.effectiveValues
315		prevArchive := j.archive
316		j.status = StatusCanceled
317		j.failureReason = ""
318		j.blockerID = 0
319		if j.finishedAt.IsZero() {
320			j.finishedAt = now
321		}
322		j.effectiveValues = nil
323		j.archive = nil
324		if err := s.persist(j); err != nil {
325			j.status = prevStatus
326			j.finishedAt = prevFinishedAt
327			j.failureReason = prevReason
328			j.blockerID = prevBlocker
329			j.effectiveValues = prevEffective
330			j.archive = prevArchive
331			return nil, err
332		}
333	
334		// 取消已确认保存：提交终态，让正在运行的计算尽快中止，并级联标记下游。
335		j.canceled.Store(true)
336		// 依赖它的等待者一并失败，且继续向更下游传播。
337		s.cascadeLocked()
338		s.notifyLocked()
339		return s.viewLocked(j), nil
340	}
341	
342	// List 按提交人和提交时间范围（两端均包含）列出记录，结果按提交先后排列。
343	// start 晚于 end 返回 [ErrInvalidTimeRange]。零值时间表示该端不限。
344	func (s *Store) List(submitter string, start, end time.Time) ([]*Job, error) {
345		s.mu.Lock()
346		defer s.mu.Unlock()
347		if !start.IsZero() && !end.IsZero() && start.After(end) {
348			return nil, fmt.Errorf("%w：起始时间 %s 晚于结束时间 %s",
349				ErrInvalidTimeRange, start.Format(time.RFC3339Nano), end.Format(time.RFC3339Nano))
350		}
351		out := make([]*Job, 0)
352		for _, j := range s.jobs { // jobs 已按 id 升序，即提交先后
353			if j.submitter != submitter {
354				continue
355			}
356			if !start.IsZero() && j.queuedAt.Before(start) {
357				continue
358			}
359			if !end.IsZero() && j.queuedAt.After(end) {
360				continue
361			}
362			out = append(out, s.viewLocked(j))
363		}
364		return out, nil
365	}
366	
367	// cascadeLocked 把“直接上游已失败/取消”的排队作业标记为失败并递归传播。
368	//
369	// 上游在提交时必须已存在，因此上游作业号必然更小，按作业号升序单趟
370	// 扫描即可让阻断沿链条传播到最下游。选择直接阻断者、确定根因与构造失败
371	// 原因统一走 blocker.go 中的规则（与重开归档同一套）：作业有多个直接上游时
372	// 按保存的依赖顺序选取最靠前的已失败/取消者，根因沿该上游已有的阻断信息
373	// 保留；作业一旦失败，其原因不再被后来发生的上游状态变化改写。
374	func (s *Store) cascadeLocked() {
375		for _, j := range s.jobs {
376			if j.status != StatusQueued || len(j.dependencies) == 0 {
377				continue
378			}
379			directID, direct, blocked := pickBlockingUpstream(j, s.byID, runtimeUpstreamBlocked)
380			if !blocked {
381				continue
382			}
383			root := blockerRoot(direct, directID)
384			s.markFailedLocked(j, blockedFailureReason(runtimeBlockedHead(direct), direct, directID, root), root)
385		}
386	}
387	
388	// pickRunnableLocked 返回提交顺序上第一个可运行的排队作业。
389	// 可运行要求全部直接上游都已成功并归档；只要还有一个上游在排队或运行，
390	// 该作业就被跳过，不挡住后面可运行的作业。
391	func (s *Store) pickRunnableLocked() *storedJob {
392		for _, j := range s.jobs {
393			if j.status != StatusQueued {
394				continue
395			}
396			if len(j.dependencies) == 0 {
397				return j
398			}
399			ready := true
400			for _, id := range j.dependencies {
401				dep := s.byID[id]
402				if dep == nil || dep.status != StatusSucceeded {
403					ready = false
404					break
405				}
406			}
407			if ready {
408				return j
409			}
410		}
411		return nil
412	}
413	
414	// notifyLocked 在持锁状态下非阻塞唤醒 worker。
415	func (s *Store) notifyLocked() {
416		select {
417		case s.waitCh <- struct{}{}:
418		default:
419		}
420	}
421	
422	// notify 在不持锁时唤醒 worker。
423	func (s *Store) notify() {
424		s.mu.Lock()
425		s.notifyLocked()
426		s.mu.Unlock()
427	}
428	
429	// persistRetry 对落盘做有限次重试，尽量避免内存状态与磁盘记录分叉。
430	func (s *Store) persistRetry(j *storedJob, attempts int) error {
431		var err error
432		for i := 0; i < attempts; i++ {
433			if err = s.persist(j); err == nil {
434				return nil
435			}
436		}
437		return err
438	}
439	
440	// worker 是本地唯一的计算执行体。
441	func (s *Store) worker() {
442		defer s.wg.Done()
443		for {
444			s.mu.Lock()
445			if s.stopping.Load() {
446				s.mu.Unlock()
447				return
448			}
449			j := s.pickRunnableLocked()
450			if j == nil {
451				ch := s.waitCh
452				s.mu.Unlock()
453				select {
454				case <-ch:
455				case <-s.stopCh:
456				}
457				continue
458			}
459	
460			// 进入运行并原子持久化该状态。
461			j.status = StatusRunning
462			j.startedAt = s.now().UTC()
463			// 实际输入 = 原始序列 + 各直接上游的总和（严格按列表顺序追加）。
464			inputs := append([]int64(nil), j.values...)
465			for _, id := range j.dependencies {
466				if dep := s.byID[id]; dep != nil && dep.archive != nil {
467					inputs = append(inputs, dep.archive.Sum)
468				}
469			}
470			seed := j.seed
471			s.runningID = j.id
472			if err := s.persistRetry(j, 3); err != nil {
473				// 连运行状态都无法落盘：保守地失败，不进行计算。
474				s.markFailedLocked(j, "无法持久化作业状态："+err.Error(), 0)
475				s.runningID = 0
476				s.cascadeLocked()
477				s.notifyLocked()
478				s.mu.Unlock()
479				continue
480			}
481			s.mu.Unlock()
482	
483			abort := func() bool { return j.canceled.Load() || s.stopping.Load() }
484			doCompute := s.compute
485			if doCompute == nil {
486				doCompute = func(_ uint64, in []int64, sd int64, c func() bool) (int64, int64, string, bool) {
487					return computeResult(in, sd, c)
488				}
489			}
490			sum, sumSq, reason, ok := doCompute(j.id, inputs, seed, abort)
491	
492			s.mu.Lock()
493			s.runningID = 0
494			switch {
495			case j.status == StatusCanceled:
496				// 用户取消已在 Cancel 中落盘；此处确保丢弃任何计算产物。
497				j.archive = nil
498				j.effectiveValues = nil
499				_ = s.persistRetry(j, 3)
500				s.cascadeLocked()
501			case s.stopping.Load():
502				s.markFailedLocked(j, "计算被中断：归档在计算过程中关闭", 0)
503				s.cascadeLocked()
504			case !ok:
505				s.markFailedLocked(j, reason, 0)
506				s.cascadeLocked()
507			default:
508				// 成功：状态与完整归档在同一条记录的同一次原子写入中可见。
509				completed := s.now().UTC()
510				a := newArchive(j, inputs, sum, sumSq, completed)
511				j.effectiveValues = append([]int64(nil), inputs...)
512				j.status = StatusSucceeded
513				j.finishedAt = completed
514				j.failureReason = ""
515				j.blockerID = 0
516				j.archive = a
517				if err := s.persistRetry(j, 3); err != nil {
518					// 落盘失败时绝不让对外可见“成功却没有归档”：回退为失败。
519					j.archive = nil
520					j.effectiveValues = nil
521					s.markFailedLocked(j, "结果归档写入失败："+err.Error(), 0)
522					// 归档写入失败与计算溢出等失败同等对待：立即沿依赖链阻断所有仍在
523					// 排队等待它的作业，使等待者无需等到下一次提交/取消即进入失败终态。
524					s.cascadeLocked()
525				}
526			}
527			s.notifyLocked()
528			s.mu.Unlock()
529		}
530	}
531	
532	// markFailedLocked 在持锁状态下把作业置为失败终态并尝试落盘。
533	func (s *Store) markFailedLocked(j *storedJob, reason string, blocker uint64) {
534		j.status = StatusFailed
535		j.failureReason = reason
536		j.blockerID = blocker
537		if j.finishedAt.IsZero() {
538			j.finishedAt = s.now().UTC()
539		}
540		j.archive = nil
541		j.effectiveValues = nil
542		_ = s.persistRetry(j, 3)
543	}
544	
545	// newArchive 构造成功归档；CompletedAt 之外的全部字段都是确定性的。
546	// 上游作业号只作记录，不参与任何摘要与校验值。
547	func newArchive(j *storedJob, effective []int64, sum, sumSquares int64, completedAt time.Time) *Archive {
548		inDigest := inputsDigestHex(effective, j.seed)
549		resDigest := resultDigestHex(effective, j.seed, sum, sumSquares)
550		log := buildLog(effective, j.seed, sum, sumSquares)
551		checksum := checksumHex(effective, j.seed, sum, sumSquares, log, resDigest)
552		var firstDep uint64
553		if len(j.dependencies) > 0 {
554			firstDep = j.dependencies[0]
555		}
556		return &Archive{
557			JobID:           j.id,
558			Submitter:       j.submitter,
559			RequestID:       j.requestID,
560			IdentityRaw:     rawIdentity(j.submitter, j.requestID),
561			Seed:            j.seed,
562			Values:          append([]int64(nil), j.values...),
563			HasDependency:   len(j.dependencies) > 0,
564			DependencyID:    firstDep,
565			Dependencies:    append([]uint64(nil), j.dependencies...),
566			EffectiveValues: append([]int64(nil), effective...),
567			InputsDigest:    inDigest,
568			Sum:             sum,
569			SumOfSquares:    sumSquares,
570			ResultDigest:    resDigest,
571			Log:             log,
572			Checksum:        checksum,
573			CompletedAt:     completedAt,
574		}
575	}
576	
577	// viewLocked 在持锁状态下生成对外只读视图，全部切片深拷贝。
578	func (s *Store) viewLocked(j *storedJob) *Job {
579		v := &Job{
580			ID:              j.id,
581			Submitter:       j.submitter,
582			RequestID:       j.requestID,
583			Seed:            j.seed,
584			Values:          append([]int64(nil), j.values...),
585			Dependencies:    append([]uint64(nil), j.dependencies...),
586			QueuedAt:        j.queuedAt,
587			StartedAt:       j.startedAt,
588			FinishedAt:      j.finishedAt,
589			Status:          j.status,
590			FailureReason:   j.failureReason,
591			BlockerID:       j.blockerID,
592			EffectiveValues: append([]int64(nil), j.effectiveValues...),
593		}
594		v.HasDependency = len(j.dependencies) > 0
595		if len(j.dependencies) > 0 {
596			v.DependencyID = j.dependencies[0]
597		}
598		if j.status == StatusQueued {
599			v.WaitReason = WaitSlot
600			// 列出尚未成功归档的直接上游，保持提交时的顺序。
601			for _, id := range j.dependencies {
602				if dep := s.byID[id]; dep == nil || dep.status != StatusSucceeded {
603					v.PendingDependencies = append(v.PendingDependencies, id)
604				}
605			}
606			if len(v.PendingDependencies) > 0 {
607				v.WaitReason = WaitDependency
608			}
609		}
610		if j.archive != nil {
611			a := *j.archive
612			a.Values = append([]int64(nil), j.archive.Values...)
613			a.EffectiveValues = append([]int64(nil), j.archive.EffectiveValues...)
614			a.Dependencies = append([]uint64(nil), j.archive.Dependencies...)
615			if j.archive.IdentityRaw != nil {
616				raw := *j.archive.IdentityRaw
617				a.IdentityRaw = &raw
618			}
619			v.Archive = &a
620		}
621		return v
622	}
623	
624	// Dir 返回归档目录路径。
625	func (s *Store) Dir() string { return s.dir }
626

