234	// syncDir 对目录本身做一次 fsync，让新建项与 rename 在崩溃后仍然成立。
235	func syncDir(dir string) {
236		if d, err := os.Open(dir); err == nil {
237			_ = d.Sync()
238			_ = d.Close()
239		}
240	}
241	
242	// loadDir 扫描目录中的全部作业记录并重建内存索引。
243	//
244	// 恢复规则：
245	//   - 上次关闭时仍为 running 的作业标记为失败，原因是计算被中断；
246	//   - 成功记录缺少归档、校验值对不上，实际输入与原始参数或直接依赖数量
247	//     不对应，或归档数值结果与有效输入按计算规则应得的结果不符时，
248	//     fail-closed 地标记为失败，维持“成功必有完整归档”的不变量；
249	//   - 有依赖的成功记录还要求每个直接上游都存在、恢复后仍是带完整归档的
250	//     成功状态，且实际输入的追加部分逐项等于这些上游按保存的依赖顺序
251	//     排列的总和；上游不可用的同样改判为失败，其失败原因指出直接上游、
252	//     BlockerID 沿链条保留最初的根因（与运行中依赖失败同一规则）；
253	//     仅追加输入对不上而上游全部有效的属于本作业自身归档有误，BlockerID
254	//     保持 0。仍在排队的作业在同一趟升序扫描中按既有依赖规则级联失败。
255	func loadDir(dir string) ([]*storedJob, uint64, error) {
256		entries, err := os.ReadDir(dir)
257		if err != nil {
258			return nil, 0, err
259		}
260		var jobs []*storedJob
261		var maxID uint64
262		for _, e := range entries {
263			name := e.Name()
264			if e.IsDir() {
265				continue
266			}
267			// 清理上一进程崩溃时可能残留的原子写临时文件。
268			if strings.HasPrefix(name, ".tmp-") {
269				_ = os.Remove(filepath.Join(dir, name))
270				continue
271			}
272			if !strings.HasPrefix(name, "job-") || !strings.HasSuffix(name, ".json") {
273				continue
274			}
275			path := filepath.Join(dir, name)
276			data, err := os.ReadFile(path)
277			if err != nil {
278				return nil, 0, err
279			}
280			var r jobRecord
281			if err := json.Unmarshal(data, &r); err != nil {
282				return nil, 0, fmt.Errorf("numeric: 记录 %s 损坏: %w", name, err)
283			}
284			if r.Version != recordVersion {
285				return nil, 0, fmt.Errorf("numeric: 记录 %s 版本不受支持: %s", name, r.Version)
286			}
287			// 提交人、请求号按完整字节恢复：含非法 UTF-8 字节时以
288			// identity_raw 兜底字段为准，普通文本（含 U+0000）与旧归档原样使用。
289			submitter, requestID, err := resolveIdentity(r.Submitter, r.RequestID, r.IdentityRaw)
290			if err != nil {
291				return nil, 0, fmt.Errorf("numeric: 记录 %s 标识损坏: %w", name, err)
292			}
293			// 成功归档内嵌同一份标识，同样按其自身兜底字段恢复，保证顶层记录
294			// 与归档中的参数逐字节一致。
295			if r.Archive != nil {
296				aSub, aReq, aErr := resolveIdentity(r.Archive.Submitter, r.Archive.RequestID, r.Archive.IdentityRaw)
297				if aErr != nil {
298					return nil, 0, fmt.Errorf("numeric: 记录 %s 归档标识损坏: %w", name, aErr)
299				}
300				r.Archive.Submitter = aSub
301				r.Archive.RequestID = aReq
302			}
303			switch r.Status {
304			case StatusQueued, StatusRunning, StatusSucceeded, StatusFailed, StatusCanceled:
305			default:
306				return nil, 0, fmt.Errorf("numeric: 记录 %s 状态非法: %q", name, r.Status)
307			}
308			// 新格式记录直接给出有序依赖列表；旧格式记录只有单依赖字段，
309			// 恢复为只含一个作业号的列表（语义与提交时一致）。
310			deps := append([]uint64(nil), r.Dependencies...)
311			if len(deps) == 0 && r.HasDependency {
312				deps = []uint64{r.DependencyID}
313			}
314			j := &storedJob{
315				id:           r.ID,
316				submitter:    submitter,
317				requestID:    requestID,
318				seed:         r.Seed,
319				values:       append([]int64(nil), r.Values...),
320				dependencies: deps,
321	
322				queuedAt:   r.QueuedAt,
323				startedAt:  r.StartedAt,
324				finishedAt: r.FinishedAt,
325	
326				status:        r.Status,
327				failureReason: r.FailureReason,
328				blockerID:     r.BlockerID,
329	
330				effectiveValues: append([]int64(nil), r.EffectiveValues...),
331				archive:         r.Archive,
332			}
333			if j.status == StatusRunning {
334				failRestoredJob(dir, j, "计算被中断：归档上次关闭时作业仍在运行", 0)
335			}
336			if j.status == StatusSucceeded {
337				// 除完整性外，还必须满足两条独立的对应/复算规则：
338				//  1. 实际输入与原始参数、直接依赖数量逐项对应——原始序列非空且
339				//     按原次序完整出现在实际输入开头，总长度恰为原始长度加上直接
340				//     依赖数；摘要、日志、校验值只与“实际输入”绑定，换成另一份
341				//     序列（如 [-3,2] 冒充 [2,-3]）仍能全套自洽，只有按位置比对
342				//     原始参数与依赖数量才能识别。
343				//  2. 归档中的数值结果必须与实际输入按既有计算规则应得的结果一致：
344				//     日志、摘要与校验值都可能与错误数字自洽，只有按保存的实际
345				//     输入复算才能识别。
346				// 任一不符合都按损坏归档处理。第三条规则——追加部分逐项等于各
347				// 直接上游恢复后的总和——需要全部记录恢复完毕才能核对，
348				// 在排序后的第二趟扫描中执行。
349				var invalidReason string
350				switch {
351				case !archiveIntact(j):
352					invalidReason = "归档不完整或校验值不一致，成功结果不可用"
353				case !effectiveInputsCorrespond(j):
354					invalidReason = "实际输入与原始参数或依赖数量不符，成功结果不可用"
355				case !archiveResultsValid(j):
356					invalidReason = "归档数值结果与有效输入按计算规则应得的结果不符，成功结果不可用"
357				}
358				if invalidReason != "" {
359					// 归档自身校验不通过：属于本作业自身失败，不携带阻断根因。
360					failRestoredJob(dir, j, invalidReason, 0)
361				}
362			}
363			jobs = append(jobs, j)
364			if j.id > maxID {
365				maxID = j.id
366			}
367		}
368		// 恢复后的排列必须与关闭前的接受先后一致：作业号在接受时单调分配，
369		// 按作业号升序即提交先后。记录上的提交时间只用于时间范围过滤，
370		// 不参与排序——本机时钟回拨会让后接受的作业带有更早的时间，
371		// 按时间重排会改变已确定的先后关系（也会让上游作业号更大的
372		// 依赖链在单趟级联扫描中漏掉失败传播）。
373		sort.Slice(jobs, func(a, b int) bool {
374			return jobs[a].id < jobs[b].id
375		})
376		// 第二趟：按作业号升序单趟处理依赖失效。直接上游在提交时必须已存在，
377		// 上游作业号必然更小，因此每个作业被处理时其全部直接上游都已是本次恢复
378		// 确定的最终状态——上游被改判失败时携带的根因作业号可直接沿链条继承，
379		// 不会在每经过一个已归档的中间作业时重新起算。
380		//
381		// 两类作业遵守同一项归因规则（与正常运行中的依赖失败一致）：失败原因
382		// 指出当前作业的直接上游，BlockerID 沿链条保留最初使结果不可用的根因；
383		// 只有本作业自身归档有误（上游全部有效、仅保存的追加输入不符）时
384		// BlockerID 才保持 0。
385		//   - 带依赖的成功记录：追加部分与上游恢复后的结果逐项核对；
386		//   - 排队记录：按保存的依赖顺序选取最靠前的不可用上游（已失败/取消，
387		//     或记录缺失），立即级联失败，不再等待。
388		byID := make(map[uint64]*storedJob, len(jobs))
389		for _, j := range jobs {
390			byID[j.id] = j
391		}
392		for _, j := range jobs {
393			if len(j.dependencies) == 0 {
394				continue
395			}
396			switch j.status {
397			case StatusSucceeded:
398				// 第一趟：按保存的依赖顺序找最靠前的不可用上游（记录缺失或恢复后
399				// 未保持带完整归档的成功状态）。
400				directID, dep, unavailable := pickBlockingUpstream(j, byID, restoredArchiveUpstreamBlocked)
401				if unavailable {
402					// 因直接上游结果失效而失败：根因沿该上游已有的阻断信息保留，
403					// 直接上游记录缺失时以缺失的作业号本身作为根因。
404					root := blockerRoot(dep, directID)
405					failRestoredJob(dir, j, blockedFailureReason(restoredArchiveHead(directID), dep, directID, root), root)
406					continue
407				}
408				// 第二趟：直接上游全部存在且有效，只是本作业保存的追加输入与上游
409				// 总和按位置对不上——属于本作业自身归档有误，不把有效上游判成
410				// 失败或归因给它，BlockerID 保持 0。
411				if _, detail, mismatch := firstAppendedMismatch(j, byID); mismatch {
412					failRestoredJob(dir, j, detail, 0)
413				}
414			case StatusQueued:
415				// 按保存的依赖顺序选取最靠前的不可用上游；其他上游作业号更小
416				// 或失败原因不同都不能改变这个选择。
417				directID, direct, blocked := pickBlockingUpstream(j, byID, restoredQueuedUpstreamBlocked)
418				if !blocked {
419					continue // 上游仍在排队等情况：继续等待，不挡住其他作业。
420				}
421				root := blockerRoot(direct, directID)
422				if direct == nil {
423					// 直接上游的记录在归档目录中缺失，其结果不可能再变为可用：
424					// 以缺失的作业号作为根因，并明确说明结果无法使用。
425					failRestoredJob(dir, j, blockedFailureReason(restoredMissingHead(directID), nil, directID, root), root)
426					continue
427				}
428				failRestoredJob(dir, j, blockedFailureReason(runtimeBlockedHead(direct), direct, directID, root), root)
429			}
430		}
431		return jobs, maxID, nil
432	}
433	
434	// failRestoredJob 收拢重新打开归档时把恢复出的作业改判为失败的统一处理，
435	// 供三类恢复失败共用（调用顺序即各类判定的既有先后）：
436	//   - 上次关闭时仍在运行的作业：计算被中断（第一趟记录扫描）；
437	//   - 原标为成功、但归档完整性、实际输入对应关系或数值结果不符规则的作业：
438	//     本作业自身归档校验失败（第一趟记录扫描，BlockerID 恒为 0）；
439	//   - 被不可用直接上游阻断的作业：成功记录复核与排队记录复查（第二趟升序扫描），
440	//     BlockerID 由调用方按 blocker.go 的归因规则给出。
441	//
442	// 处理内容与各处原先内联的步骤完全一致：置失败状态、失败原因与阻断根因；
443	// 已经有完成时间的记录保留该时间，只有没有完成时间的才补上当前时间；
444	// 清除成功归档与实际参与计算的输入，使按作业号读取与按提交人列举都不再返回
445	// 成功归档或实际输入；作业号、提交人、请求号、原始整数次序、种子、依赖次序
446	// 与已有开始时间均不在此改动。归档可正常写入时，变化经同一条记录的一次
447	// 原子替换写回磁盘，而不只停留在内存查询结果中；写入失败维持既有尽力而为
448	// 语义（不因恢复阶段的一次落盘失败让整个归档无法打开）。
449	func failRestoredJob(dir string, j *storedJob, reason string, blocker uint64) {
450		j.status = StatusFailed
451		j.failureReason = reason
452		j.blockerID = blocker
453		if j.finishedAt.IsZero() {
454			j.finishedAt = time.Now().UTC()
455		}
456		j.effectiveValues = nil
457		j.archive = nil
458		if data, err := encodeRecord(j); err == nil {
459			_ = writeFileAtomic(dir, jobFileName(j.id), data, 0o600)
460		}
461	}
462	
463	// archiveIntact 复算成功归档的全部确定性字段，任何不一致都视为不可用。
464	func archiveIntact(j *storedJob) bool {
465		a := j.archive
466		if a == nil {
467			return false
468		}
469		// 归档中的原始参数必须与记录顶层字段一致。
470		if a.JobID != j.id || a.Submitter != j.submitter || a.RequestID != j.requestID ||
471			a.Seed != j.seed || a.HasDependency != (len(j.dependencies) > 0) {
472			return false
473		}
474		if a.HasDependency && a.DependencyID != depID(j) {
475			return false
476		}
477		// 依赖列表（内容与次序）必须一致。旧格式归档没有 dependencies 字段，
478		// 由单依赖字段推导后再比较。
479		aDeps := append([]uint64(nil), a.Dependencies...)
480		if len(aDeps) == 0 && a.HasDependency {
481			aDeps = []uint64{a.DependencyID}
482		}
483		if len(aDeps) != len(j.dependencies) {
484			return false
485		}
486		for i := range j.dependencies {
487			if aDeps[i] != j.dependencies[i] {
488				return false
489			}
490		}
491		if len(a.Values) != len(j.values) {
492			return false
493		}
494		for i := range j.values {
495			if a.Values[i] != j.values[i] {
496				return false
497			}
498		}
499		if len(j.effectiveValues) == 0 || len(a.EffectiveValues) != len(j.effectiveValues) {
500			return false
501		}
502		for i := range j.effectiveValues {
503			if j.effectiveValues[i] != a.EffectiveValues[i] {
504				return false
505			}
506		}
507		if a.InputsDigest != inputsDigestHex(j.effectiveValues, j.seed) {
508			return false
509		}
510		if a.ResultDigest != resultDigestHex(j.effectiveValues, j.seed, a.Sum, a.SumOfSquares) {
511			return false
512		}
513		if a.Log != buildLog(j.effectiveValues, j.seed, a.Sum, a.SumOfSquares) {
514			return false
515		}
516		if a.Checksum != checksumHex(j.effectiveValues, j.seed, a.Sum, a.SumOfSquares, a.Log, a.ResultDigest) {
517			return false
518		}
519		return true
520	}
521	
522	// archiveResultsValid 按既有计算规则对归档保存的实际输入（effectiveValues，
523	// 已含按顺序追加的上游总和，不再追加）复算总和与平方和，归档中的数值结果
524	// 必须与复算结果完全一致。完整性检查只验证日志、摘要与校验值和所写数字
525	// 自洽，无法识别“数字本身写错但全套字段一致”的记录，因此这里以计算规则
526	// 为准。实际输入按规则会造成 int64 溢出时 ok 为 false，任何数值结果
527	// （包括回绕后的值）都不能作为有效成功结果保留。
528	//
529	// 调用前须已通过 archiveIntact（保证 archive 非空且有效输入非空）。
530	func archiveResultsValid(j *storedJob) bool {
531		a := j.archive
532		sum, sumSquares, _, ok := computeResult(j.effectiveValues, j.seed, nil)
533		if !ok {
534			return false
535		}
536		return a.Sum == sum && a.SumOfSquares == sumSquares
537	}
538	
539	// effectiveInputsCorrespond 校验成功记录中实际参与计算的输入与原始提交
540	// 参数、直接依赖数量之间的对应关系：
541	//   - 原始序列必须非空；
542	//   - 原始序列逐项、按原次序完整出现在实际输入的开头——负数、零与重复
543	//     整数一律按位置判断，不比较总和或平方和，也不忽略次序；
544	//   - 实际输入总长度必须恰好等于原始序列长度加直接依赖数量。无依赖时两份
545	//     序列必须完全相同；有单个或多个依赖时，原始部分之后只能保留每个直接
546	//     上游各占一个位置的追加部分，不能借依赖之名替换、截短原始部分，也不
547	//     能多出未记录的输入。
548	//
549	// 该规则防止把另一份输入的自洽结果挂在原始参数下：例如原始参数为 [2,-3]
550	// 而实际输入被换成 [-3,2] 时，总和与平方和不变，摘要、日志与校验值又只
551	// 绑定实际输入，全套字段仍会自洽，只有按位置比对原始参数并核对追加数量
552	// 才能识别。旧的单依赖记录恢复后依赖列表恰含一个作业号，按同一含义判断。
553	//
554	// 调用前须已通过 archiveIntact（保证 archive 非空、实际输入非空且归档内
555	// 副本与顶层一致）。
556	func effectiveInputsCorrespond(j *storedJob) bool {
557		n := len(j.values)
558		if n == 0 {
559			return false
560		}
561		if len(j.effectiveValues) != n+len(j.dependencies) {
562			return false
563		}
564		for i := 0; i < n; i++ {
565			if j.effectiveValues[i] != j.values[i] {
566				return false
567			}
568		}
569		return true
570	}
571

